"""Generate queue message types from JSON Schema (ADR-0010 item 1, ADR-0014).

Each file in packages/db/messages/ is one message; its name is also its queue name. The
same schemas become zod for the web app and pydantic for the worker, so a message is
defined once (ARCH-2).

Usage: python -m interval_db.messages_codegen <messages dir> <ts out> <py out>
"""

import json
import re
import sys
from pathlib import Path
from typing import Any

NAME = re.compile(r"^[a-z][a-z0-9]*(_[a-z0-9]+)*$")
SUFFIX = ".schema.json"
HEADER = (
    "Generated by interval_db.messages_codegen from packages/db/messages. Do not edit."
)


class UnsupportedSchemaError(Exception):
    """A schema uses JSON Schema beyond the subset both generators understand."""


def load(directory: Path) -> dict[str, dict[str, Any]]:
    schemas: dict[str, dict[str, Any]] = {}
    for path in sorted(directory.glob(f"*{SUFFIX}")):
        schemas[path.name.removesuffix(SUFFIX)] = json.loads(path.read_text("utf-8"))
    return schemas


# Anything else would be silently ignored, leaving the generated validators looser
# than the schema reads.
TOP_LEVEL = frozenset(
    {"$schema", "description", "type", "additionalProperties", "required", "properties"}
)
# Names that would shadow pydantic's own attributes.
RESERVED = frozenset({"model_config", "model_fields", "model_computed_fields"})


def _properties(name: str, schema: dict[str, Any]) -> list[tuple[str, dict[str, Any]]]:
    unknown = set(schema) - TOP_LEVEL
    if unknown:
        raise UnsupportedSchemaError(f"{name}: unsupported keywords {sorted(unknown)}")
    description = schema.get("description", "")
    if not isinstance(description, str) or any(c in description for c in '\n"\\'):
        raise UnsupportedSchemaError(
            f"{name}: description must be one line without quotes or backslashes"
        )
    if schema.get("type") != "object":
        raise UnsupportedSchemaError(f"{name}: type must be object")
    if schema.get("additionalProperties") is not False:
        raise UnsupportedSchemaError(f"{name}: additionalProperties must be false")
    properties: dict[str, dict[str, Any]] = schema.get("properties", {})
    for required in schema.get("required", []):
        if required not in properties:
            raise UnsupportedSchemaError(
                f"{name}: required {required!r} isn't a property"
            )
    return sorted(properties.items())


def _check(name: str, prop: str, spec: dict[str, Any]) -> None:
    if not NAME.match(prop) or prop in RESERVED:
        raise UnsupportedSchemaError(f"{name}.{prop}: property names are snake_case")
    kind = spec.get("type")
    if kind is not None and not isinstance(kind, str):
        raise UnsupportedSchemaError(f"{name}.{prop}: type must be one string")
    if kind is None and not spec.get("enum"):
        raise UnsupportedSchemaError(f"{name}.{prop}: enum must list values")
    allowed = {
        "integer": {"type", "minimum", "description"},
        "string": {"type", "minLength", "format", "description"},
        "boolean": {"type", "description"},
        None: {"enum", "description"},
    }
    if kind not in allowed or not set(spec) <= allowed[kind]:
        raise UnsupportedSchemaError(f"{name}.{prop}: unsupported {sorted(spec)}")
    if kind is None and not all(isinstance(v, str) for v in spec.get("enum", [None])):
        raise UnsupportedSchemaError(f"{name}.{prop}: enum values must be strings")
    if spec.get("format", "uri") != "uri":
        raise UnsupportedSchemaError(f"{name}.{prop}: only format uri is supported")


def _zod(spec: dict[str, Any]) -> str:
    kind = spec.get("type")
    if kind is None:
        return f"z.enum([{', '.join(json.dumps(v) for v in spec['enum'])}])"
    if kind == "integer":
        minimum = spec.get("minimum")
        return "z.number().int()" + ("" if minimum is None else f".min({minimum})")
    if kind == "boolean":
        return "z.boolean()"
    # format uri means a web address: http(s) only, never javascript: or file:.
    base = (
        "z.url({ protocol: /^https?$/ })"
        if spec.get("format") == "uri"
        else "z.string()"
    )
    length = spec.get("minLength")
    return base + ("" if length is None else f".min({length})")


def _pydantic(spec: dict[str, Any]) -> str:
    kind = spec.get("type")
    if kind is None:
        return f"Literal[{', '.join(json.dumps(v) for v in spec['enum'])}]"
    if kind == "integer":
        minimum = spec.get("minimum")
        return "int" if minimum is None else f"Annotated[int, Field(ge={minimum})]"
    if kind == "boolean":
        return "bool"
    if spec.get("format") == "uri":
        return "Uri"
    length = spec.get("minLength")
    return "str" if length is None else f"Annotated[str, Field(min_length={length})]"


def _class(name: str) -> str:
    return "".join(part.capitalize() for part in name.split("_"))


def render(schemas: dict[str, dict[str, Any]]) -> tuple[str, str]:
    ts_entries: list[str] = []
    py_classes: list[str] = []
    for name, schema in sorted(schemas.items()):
        if not NAME.match(name):
            raise UnsupportedSchemaError(f"{name}: message names are snake_case")
        required = set(schema.get("required", []))
        ts_fields: list[str] = []
        py_fields: list[str] = []
        for prop, spec in _properties(name, schema):
            _check(name, prop, spec)
            optional = prop not in required
            ts_fields.append(
                f"    {prop}: {_zod(spec)}{'.optional()' if optional else ''},"
            )
            annotation = _pydantic(spec)
            py_fields.append(
                f"    {prop}: {annotation} | None = None"
                if optional
                else f"    {prop}: {annotation}"
            )
        description = schema.get("description", "")
        ts_entries.append(
            f"  // {description}\n  {name}: z.strictObject({{\n"
            + "\n".join(ts_fields)
            + "\n  }),"
        )
        py_classes.append(
            f'class {_class(name)}(_Message):\n    """{description}"""\n\n'
            + ("\n".join(py_fields) or "    pass")
        )

    names = sorted(schemas)
    typescript = (
        f"// {HEADER}\n"
        'import { z } from "zod";\n\n'
        "export const messageSchemas = {\n"
        + "\n".join(ts_entries)
        + "\n} as const;\n\n"
        "export type MessageName = keyof typeof messageSchemas;\n"
        "export type Messages = {\n"
        "  [N in MessageName]: z.infer<(typeof messageSchemas)[N]>;\n"
        "};\n"
    )
    python = (
        f'"""{HEADER}"""\n\n'
        "from typing import Annotated, Literal\n\n"
        "from pydantic import (\n"
        "    AfterValidator,\n    AnyUrl,\n    BaseModel,\n"
        "    ConfigDict,\n    Field,\n"
        ")\n\n\n"
        "def _uri(value: str) -> str:\n"
        "    # A web address (http or https), kept as the string sent.\n"
        "    if AnyUrl(value).scheme not in ('http', 'https'):\n"
        "        raise ValueError('only http and https URLs')\n"
        "    return value\n\n\n"
        "type Uri = Annotated[str, AfterValidator(_uri)]\n\n\n"
        "class _Message(BaseModel):\n"
        '    model_config = ConfigDict(extra="forbid", frozen=True, strict=True)\n\n\n'
        + "\n\n\n".join(py_classes)
        + "\n\n\n"
        f"type MessageName = Literal[{', '.join(json.dumps(n) for n in names)}]\n\n"
        "MESSAGES: dict[MessageName, type[_Message]] = {\n"
        + "".join(f'    "{n}": {_class(n)},\n' for n in names)
        + "}\n"
    )
    return typescript, python


def main(argv: list[str]) -> None:
    directory, ts_out, py_out = (Path(a) for a in argv)
    typescript, python = render(load(directory))
    ts_out.write_text(typescript, encoding="utf-8")
    py_out.write_text(python, encoding="utf-8")


if __name__ == "__main__":
    main(sys.argv[1:])
